// Deterministische Kontrolle nach dem Modell. Die Schwelle ist ein Vorschlag und wird mit E4 kalibriert.
const SCHWELLE = 0.7;
const ERLAUBT = ['inklusive', 'zusatzleistung', 'unklar'];
const KATEGORIEN = ['A', 'B', 'C', 'E'];
const LEER = ['', 'NULL', 'NONE', 'N/A', '-'];
const norm = s => String(s ?? '').toLowerCase().replace(/[*_`|]/g, ' ').replace(/\s+/g, ' ').trim();
const vertrag = norm($('Vertragstext lesen').first().json.data);
const ticketId = $('Eingang normalisieren').first().json.ticketId;
const kundeId = $('Eingang normalisieren').first().json.kundeId;
const klasse = $('Anfrage klassifizieren').first().json.output?.klasse ?? '';
const items = $input.all();
const quellen = items.length > 0 ? items : [{ json: {} }];
return quellen.map(item => {
  const a = item.json.output ?? {};
  const zitat = norm(a.zitat);
  const zitatOk = zitat.length >= 15 && vertrag.includes(zitat);
  const rawKat = String(a.kategorie ?? '').trim().toUpperCase();
  const kat = KATEGORIEN.includes(rawKat) ? rawKat : null;
  const gruende = [];
  if (!ERLAUBT.includes(a.urteil)) gruende.push('Urteil fehlt oder ungültig');
  if (a.urteil === 'unklar') gruende.push('Urteil unklar');
  if (a.urteil !== 'unklar' && !zitatOk) gruende.push('Zitat nicht wörtlich im Vertrag gefunden');
  if (!(Number(a.sicherheit) >= SCHWELLE)) gruende.push('Sicherheit unter Schwelle');
  if (a.urteil === 'zusatzleistung' && !kat) gruende.push('Kategorie fehlt oder ungültig');
  if (!kat && !LEER.includes(rawKat)) gruende.push('Kategorie ungültig: ' + rawKat);
  return { json: {
    ticketId, kundeId, klasse,
    urteil: a.urteil ?? null, fundstelle: a.fundstelle ?? null, zitat: a.zitat ?? null, kategorie: kat,
    begruendung: a.begruendung ?? null, sicherheit: a.sicherheit ?? null,
    zitatOk, eskalieren: gruende.length > 0, grund: gruende.join('; '),
    preis: null,
    preisHinweis: 'Preis nach Regel (Stundensatz mal Aufwand), Stundensatz und Aufwand noch nicht angebunden'
  } };
});

// Kontingent gegenprüfen: rechnet der Code, nicht das Modell. Quelle: Sheet Kontingentkonten Capstone, Tab Kunde <ID>.
const basis = $('Fundstelle prüfen und Eskalation bestimmen').first().json;
const konto = {};
for (const item of $input.all()) {
  const r = item.json;
  if (r['Feld'] !== undefined && r['Feld'] !== null && String(r['Feld']).trim() !== '') konto[String(r['Feld']).trim()] = r['Wert'];
}
const num = v => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim();
  return s === '' ? NaN : Number(s.replace(',', '.'));
};
const iso = v => {
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  const s = String(v ?? '').trim();
  if (s.length >= 10 && s[4] === '-' && s[7] === '-') return s.slice(0, 10);
  const p = s.split('.');
  if (p.length === 3 && p[2].length === 4) return p[2] + '-' + p[1].padStart(2, '0') + '-' + p[0].padStart(2, '0');
  return '';
};
const heute = $now.toISODate();
const einheit = String(konto['Einheit'] ?? '');
const gesamt = num(konto['Gesamt']);
const verbraucht = num(konto['Verbraucht']);
const restSheet = num(konto['Rest']);
const von = iso(konto['Periode von']);
const bis = iso(konto['Periode bis']);
const maxKatA = num(konto['Max. Aufwand Kategorie A (in Einheit)']);
const rest = gesamt - verbraucht;
const k = { einheit, gesamt, verbraucht, rest, periodeVon: von, periodeBis: bis, regel: String(konto['Regel'] ?? '') };
let status, text;
if (!Number.isFinite(gesamt) || !Number.isFinite(verbraucht) || !von || !bis) {
  status = 'konto_unlesbar'; text = 'Kontingentkonto nicht lesbar oder unvollständig';
} else if (Number.isFinite(restSheet) && Math.abs(restSheet - rest) > 0.01) {
  status = 'konto_unplausibel'; text = 'Rest im Sheet weicht von Gesamt minus Verbraucht ab';
} else if (heute < von || heute > bis) {
  status = 'periode_abgelaufen'; text = 'Heute liegt außerhalb der Periode ' + von + ' bis ' + bis;
} else if (einheit === 'Seiten') {
  status = 'seiten_info'; text = 'Seitenkontingent (gilt nur für das Einlesen neuer Dokumente): Rest ' + rest + ' von ' + gesamt + ' Seiten, Seitenzahl der Anfrage nicht ermittelt';
} else if (basis.kategorie === 'C') {
  status = 'nicht_im_kontingent'; text = 'Kategorie C wird nie auf das Kontingent gebucht';
} else if (rest <= 0) {
  status = 'aufgebraucht'; text = 'Kontingent aufgebraucht (Rest ' + rest + ' ' + einheit + ')';
} else if (basis.kategorie === 'B') {
  status = 'aufwand_offen'; text = 'Rest ' + rest + ' von ' + gesamt + ' ' + einheit + ', den Aufwand der Kategorie B kalkuliert ein Mitarbeiter';
} else if (Number.isFinite(maxKatA)) {
  const nach = Math.round((rest - maxKatA) * 10) / 10;
  k.geschaetzterVerbrauchMax = maxKatA;
  k.restNachAnfrage = nach;
  status = nach < 0 ? 'knapp' : 'ausreichend';
  text = 'Rest ' + rest + ' von ' + gesamt + ' ' + einheit + ', diese Änderung höchstens ' + maxKatA + ', danach ' + nach + ' (' + status + ')';
} else {
  status = 'konto_unlesbar'; text = 'Höchstaufwand der Kategorie A fehlt im Konto';
}
k.status = status;
const blockt = ['konto_unlesbar', 'konto_unplausibel', 'periode_abgelaufen', 'aufgebraucht', 'knapp'];
const eskKontingent = blockt.includes(status);
const urteilGeaendert = eskKontingent && basis.urteil === 'inklusive' && ['aufgebraucht', 'knapp', 'periode_abgelaufen'].includes(status);
const gruende = [basis.grund, eskKontingent ? 'Kontingent: ' + text : ''].filter(Boolean).join('; ');
return [{ json: { ...basis, urteilModell: basis.urteil, urteil: urteilGeaendert ? 'zusatzleistung' : basis.urteil, kontingent: k, kontingentText: text, eskalieren: basis.eskalieren || eskKontingent, grund: gruende } }];

// Bestimmt den Fall, der spaeter den Standard-Antworttext auswaehlt, und baut
// die Slack-Karte fuer die Projektleitung. Rechnet der Code, nicht das Modell.
const d = $input.first().json;
const kat = d.kategorie ?? null;
const urteil = d.urteil ?? null;
const klasse = d.klasse ?? '';
const kont = d.kontingent ?? {};

// Freigabegrenze je Kunde in EUR. Gehoert in den Kundenstamm, hier vorlaeufig.
const FREIGABEGRENZE = { A: null, B: 1500, C: 500, D: 500, E: 500 };
const grenze = FREIGABEGRENZE[d.kundeId] ?? null;

// Solange der Aufwand nicht angebunden ist (preis === null), entscheidet der
// Kontingentstatus, ob eine Kategorie A noch innerhalb liegt.
const knapp = ['knapp', 'aufgebraucht', 'periode_abgelaufen'].includes(kont.status);

let fall;
if (klasse === 'Bugreport') fall = 'bug';
else if (kat === 'E') fall = 'e';
else if (kat === 'C') fall = 'c';
else if (kat === 'B') fall = 'b';
else if (urteil === 'inklusive' || kat === 'A') fall = knapp ? 'a_ausserhalb' : 'a_innerhalb';
else fall = 'pruefung';

const TITEL = {
  bug: 'Fehlermeldung',
  a_innerhalb: 'Kategorie A, innerhalb der Freigabegrenze',
  a_ausserhalb: 'Kategorie A, Kundenfreigabe nötig',
  b: 'Kategorie B, Zusatzleistung',
  c: 'Kategorie C, größere Änderung',
  e: 'Kategorie E, erforderliche Änderung',
  pruefung: 'Unklar, bitte selbst einordnen'
};

// Lesbare Ticketnummer. Die endgueltige Nummer gehoert an den Eingang, damit
// Antworten des Kunden demselben Ticket zugeordnet werden koennen.
const ticket = String(d.ticketId ?? '').startsWith('CR-') ? d.ticketId : 'CR-' + $now.toFormat('yyyy') + '-' + String(d.ticketId ?? '').replace(/[^0-9]/g, '').padStart(4, '0');

const z = v => (v === null || v === undefined || v === '' ? '—' : String(v));
const sicher = Number.isFinite(Number(d.sicherheit)) ? Math.round(Number(d.sicherheit) * 100) + ' %' : '—';

const slackText = [
  '*' + ticket + ' · Kunde ' + z(d.kundeId) + ' · ' + TITEL[fall] + '*',
  '',
  '*Vorschlag des Systems*',
  '• Klasse: ' + z(klasse),
  '• Urteil: ' + z(urteil) + (kat ? ', Kategorie ' + kat : ''),
  '• Begründung: ' + z(d.begruendung),
  '• Fundstelle: ' + z(d.fundstelle) + (d.zitatOk ? ' (Zitat im Vertrag belegt)' : ' (Zitat nicht belegt)'),
  '• Sicherheit: ' + sicher,
  '• Kontingent: ' + z(d.kontingentText),
  grenze ? '• Freigabegrenze dieses Kunden: ' + grenze + ' EUR' : '• Freigabegrenze dieses Kunden: noch nicht festgelegt',
  d.grund ? '• Hinweis: ' + d.grund : '',
  '',
  '*Vorgeschlagener Antworttext an den Kunden*',
  '> ' + TITEL[fall],
  '',
  'Freigeben schickt die Mail an den Kunden. Ablehnen fragt nach einer Begründung.'
].filter(Boolean).join('\n');

return [{ json: { ...d, ticket, fall, fallTitel: TITEL[fall], freigabegrenze: grenze, slackText } }];

// Waehlt den Standard-Antworttext. Sieben Faelle plus Ablehnung.
// Kein Preis, keine Zusage ueber den Vertrag hinaus: das darf nach Ziffer 6.4
// nur ein Mitarbeiter, und seine Freigabe liegt bereits vor.
const basis = $('Fall und Antwortvorschlag aufbereiten').first().json;
const ein = $input.first().json;

// Abgelehnt, wenn dieser Zweig aus der Begruendungsabfrage kommt.
const ablehnung = ein.data?.text ?? ein.data?.freeText ?? null;
const abgelehnt = ablehnung !== null;
const freigeber = ein.data?.responder?.name ?? ein.data?.responder ?? 'ein Mitarbeiter';

const t = basis.ticket;
const begr = basis.begruendung ? String(basis.begruendung) : 'siehe beigefügte Fundstelle';
const fund = basis.fundstelle ? ' (Fundstelle: ' + basis.fundstelle + ')' : '';

const kopf = 'Guten Tag,\n\nvielen Dank für Ihre Nachricht. Wir haben Ihr Anliegen unter der Ticketnummer ' + t + ' aufgenommen.\n\n';

// Hinweis auf das Ueberpruefungsrecht nach Ziffer 6.5. Entfaellt, wo keine
// Einordnung mitgeteilt wird (Fehlermeldung, offene Pruefung).
const ueberpruefung = 'Sie können innerhalb von 5 Arbeitstagen nach Zugang dieser Nachricht verlangen, dass ein Mitarbeiter die Einordnung überprüft. Bis zu einer Entscheidung ruhen Umsetzung und Abrechnung der betroffenen Änderung.\n\n';

// Hinweispflicht auf den KI-Einsatz nach Ziffer 6.9.
const fuss = 'Zur Vorbereitung der Einordnung setzen wir ein KI-gestütztes System ein. Die Entscheidung und die Freigabe dieser Nachricht liegen bei einem Mitarbeiter.\n\nMit freundlichen Grüßen\n[ABSENDER]';

const TEXTE = {
  bug: {
    betreff: 'Ihre Fehlermeldung ' + t,
    body: kopf + 'Wir haben Ihre Meldung als Fehlermeldung aufgenommen. Sie läuft nicht über das Änderungsverfahren; es gelten die vertraglich vereinbarten Reaktions- und Behebungszeiten innerhalb der Servicezeiten. Unsere Entwicklung prüft den Fehler und meldet sich mit der voraussichtlichen Dauer.\n\n' + fuss
  },
  a_innerhalb: {
    betreff: 'Ihr Änderungswunsch ' + t + ': wird umgesetzt',
    body: kopf + 'Wir haben Ihren Änderungswunsch als Kleinstveränderung (Kategorie A) eingeordnet. Begründung: ' + begr + fund + '.\n\nDie Änderung ist vom vereinbarten Leistungsumfang gedeckt und wird umgesetzt. Ein Nachtrag ist dafür nicht erforderlich.\n\n' + ueberpruefung + fuss
  },
  a_ausserhalb: {
    betreff: 'Ihr Änderungswunsch ' + t + ': Ihre Freigabe erforderlich',
    body: kopf + 'Wir haben Ihren Änderungswunsch als Kleinstveränderung (Kategorie A) eingeordnet. Begründung: ' + begr + fund + '.\n\nDer geschätzte Aufwand liegt über der vertraglich vereinbarten Freigabegrenze beziehungsweise das vereinbarte Kontingent reicht nicht aus. Bevor wir mit der Umsetzung beginnen, benötigen wir daher Ihre Freigabe in Textform. Eine Aufwandsschätzung erhalten Sie gesondert von Ihrem Ansprechpartner.\n\n' + ueberpruefung + fuss
  },
  b: {
    betreff: 'Ihr Änderungswunsch ' + t + ': Zusatzleistung',
    body: kopf + 'Wir haben Ihren Änderungswunsch als Zusatzleistung (Kategorie B) eingeordnet. Begründung: ' + begr + fund + '.\n\nSie erhalten von uns eine Aufwandsschätzung mit Angabe der Auswirkung auf Termin und Vergütung. Mit der Umsetzung beginnen wir erst nach Ihrer Bestätigung in Textform.\n\n' + ueberpruefung + fuss
  },
  c: {
    betreff: 'Ihr Änderungswunsch ' + t + ': größere Änderung',
    body: kopf + 'Wir haben Ihren Änderungswunsch als größere Änderung (Kategorie C) eingeordnet. Begründung: ' + begr + fund + '.\n\nWir erstellen Ihnen dazu ein Einzelangebot. Die Änderung wird als Nachtrag zum bestehenden Vertrag oder in einem gesonderten Vertrag vereinbart. Betroffene Termine vereinbaren wir mit Ihnen neu.\n\n' + ueberpruefung + fuss
  },
  e: {
    betreff: 'Ihr Änderungswunsch ' + t + ': erforderliche Änderung',
    body: kopf + 'Ein Mitarbeiter hat Ihren Änderungswunsch als erforderliche Änderung (Kategorie E) eingeordnet. Begründung: ' + begr + fund + '.\n\nDie Änderung ist erforderlich, um den vertraglich geschuldeten Erfolg zu erreichen oder zu sichern, und wird ohne Zusatzentgelt umgesetzt. Verschiebt sie einen vereinbarten Termin, melden wir uns dazu gesondert.\n\n' + ueberpruefung + fuss
  },
  pruefung: {
    betreff: 'Ihr Anliegen ' + t + ': in Prüfung',
    body: kopf + 'Ihr Anliegen wird derzeit von einem Mitarbeiter geprüft. Eine Einordnung und das weitere Vorgehen teilen wir Ihnen gesondert mit.\n\n' + fuss
  }
};

let betreff, body;
if (abgelehnt) {
  betreff = 'Ihr Anliegen ' + t + ': Rückmeldung';
  body = kopf + 'Ihr Anliegen wurde von einem Mitarbeiter geprüft. Wir können es nicht wie beantragt umsetzen.\n\nBegründung: ' + String(ablehnung).trim() + '\n\nIhr Anliegen bleibt unter der genannten Ticketnummer erfasst. Für Rückfragen steht Ihnen Ihr Ansprechpartner zur Verfügung.\n\n' + ueberpruefung + fuss;
} else {
  const w = TEXTE[basis.fall] ?? TEXTE.pruefung;
  betreff = w.betreff;
  body = w.body;
}

return [{ json: { ...basis, betreff, body, abgelehnt, ablehnungsgrund: ablehnung, freigeber, freigabeZeit: $now.toISO() } }];
